def esc(value):
    return html.escape(str(value), quote=True)

def figure(name, caption=None):
    path = ROOT / "codex-evidence" / name
    mime = "image/jpeg" if path.suffix == ".jpg" else "image/png"
    uri = "data:" + mime + ";base64," + base64.b64encode(path.read_bytes()).decode()
    phone = name.startswith("android")
    return f'<figure class="{"phone" if phone else "desktop"}"><a href="{uri}" target="_blank" aria-label="Open full-size evidence: {esc(name)}"><img loading="lazy" src="{uri}" alt="{esc(caption or name)}"></a><figcaption>{esc(caption or name)}</figcaption></figure>'

finding_markup = []
for f in findings:
    steps = "".join(f"<li>{esc(s)}</li>" for s in f["steps"])
    media = "".join(figure(n) for n in f["evidence"])
    finding_markup.append(f'''<article class="finding" data-platform="{f['platform']}" data-priority="{f['priority']}">
<details {'open' if f['priority']=='P2' else ''}><summary><span class="issue-id">{f['id']}</span><span class="issue-title">{esc(f['title'])}</span><span class="badge {f['priority'].lower()}">{f['priority']}</span><span class="platform">{f['platform']}</span></summary>
<div class="finding-body"><p class="impact">{esc(f['impact'])}</p><h4>Reproduce</h4><ol>{steps}</ol><div class="comparison"><div><h4>Observed</h4><p>{esc(f['actual'])}</p></div><div><h4>Expected improvement</h4><p>{esc(f['expected'])}</p></div></div>{f'<div class="evidence">{media}</div>' if media else '<p class="small">Evidence: observed UI interaction recorded in the review notes; no dedicated screenshot.</p>'}</div></details></article>''')

